void Solver::rephase() {
    rephases = 0;
    threshold *= 0.9;
    rephase_limit += 8192;

    // Mix current saved phases with local best phases based on recent performance
    double fast_avg = lbd_queue_size == 50 ? fast_lbd_sum / 50.0 : 0;
    double slow_avg = conflicts > 0 ? slow_lbd_sum / conflicts : 0;

    if (lbd_queue_size == 50 && fast_avg > slow_avg * 1.2) {
        // Recent performance is worse than long-term average
        // Reset phases to local best more aggressively
        for (int i = 1; i <= vars; i++) {
            if (rand() % 100 < 70) saved[i] = local_best[i];
            else if (rand() % 100 < 10) saved[i] = -saved[i];
        }
    } else if (fast_avg < slow_avg * 0.8) {
        // Recent performance is better than long-term average
        // Keep current phases but add some noise
        for (int i = 1; i <= vars; i++) {
            if (rand() % 100 < 10) saved[i] = rand() % 2 ? 1 : -1;
        }
    } else {
        // Balanced performance - mix current phases with local best
        for (int i = 1; i <= vars; i++) {
            if (rand() % 100 < 40) saved[i] = local_best[i];
            else if (rand() % 100 < 10) saved[i] = -saved[i];
        }
    }
}
